UPDATE CUST_INDEX_RESULT
SET val_${slot} = NULL, updated_time = NOW()
WHERE data_date = #{dataDate} AND version = #{version}

mapper.select:
SELECT val_${slot}
FROM CUST_INDEX_RESULT
WHERE cust_id = (SELECT cust_no FROM CUST_MASTER WHERE id = #{custId})
  AND data_date = #{dataDate}
ORDER BY updated_time DESC
LIMIT 1

SELECT cust_id AS custId,
       val_${slot} AS metricValue
FROM CUST_INDEX_RESULT
WHERE data_date = #{dataDate}
  AND version = #{version}
  AND cust_id IN

        #{c}

SELECT val_${slot}
FROM CUST_INDEX_RESULT
WHERE cust_id = #{subject}
  AND data_date = #{dataDate}
  AND version = #{version}
LIMIT 1

SELECT version
FROM CUST_INDEX_RESULT
WHERE cust_id = #{subject}
  AND data_date = #{dataDate}
ORDER BY updated_time DESC, version DESC
LIMIT 1

SELECT DISTINCT cust_id
FROM CUST_INDEX_RESULT
WHERE data_date = #{dataDate}
  AND version = #{version}
ORDER BY cust_id
